async function rates(){const r=await db.list<any>('delivery_settings',{limit:1});return r.items[0]||{baseFee:300,perKm:180,minFee:300};}
async function platformSettings(){const r=await db.list<any>('platform_settings',{limit:1});return r.items[0]||{commissionPct:3,minOrderAmount:0,maintenanceMode:false};}
const rad=(n:number)=>n*Math.PI/180;const distance=(a:number,b:number,c:number,d:number)=>{const R=6371,x=rad(c-a),y=rad(d-b),h=Math.sin(x/2)**2+Math.cos(rad(a))*Math.cos(rad(c))*Math.sin(y/2)**2;return R*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))};
async function profile(uid:string){const r=await db.list<any>('profiles',{limit:200});return r.items.find(x=>x.userId===uid)||null}
async function notifyUser(userId:string,title:string,body:string,data:any={}){try{await db.add('notifications',[{userId,title,body,data,read:false,createdAt:Date.now()}])}catch{}try{await notifications.send({userIds:[userId],notification:{title,body}})}catch{}}
async function order(id:string,uid:string){const r=await db.list<any>('orders',{limit:200});return r.items.find(x=>x.id===id&&x.userId===uid)||null}
async function ticketForUser(uid:string){const r=await db.list<any>('support_tickets',{limit:200});return r.items.find(x=>x.userId===uid&&x.status!=='RESOLVED')||null}
